questionvariables.text:
/* Conditions for (a) should be "noH" and "noT" where noH != 3 - noT */
noH:rand(4);
noT:rand_with_prohib(0,3,[3-noH]);

textH: if noH=0 then "zero heads" else if noH=1 then "one head" else if noH=2 then "two heads" else "three heads";
textT: if noT=0 then "zero tails" else if noT=1 then "one tail" else if noT=2 then "two tails" else "three tails";

probA: ((if noH=0 or noH=3 then 1 else 3) + (if noT=0 or noT=3 then 1 else 3))/8

/* (b) be should either be a sum with total between 5 and 9 inc. or a product of 4, 6, or 12 */
operation:rand(["sum","product"]);
total: if operation="product" then rand([4,6,12]) else (rand(5)+5);

probB: if operation="product" then (if total=4 then 1/12 else 1/9) else (if total=7 then 1/6 else if (total=6 or total=8) then 5/36 else 1/9);

/* (c) keep number of balls of each colour between 2 and 8 and the sum below 12 */
noRed:rand(7)+2;
noYel:rand_with_prohib(2,min(12-noRed,8),[noRed]);

probC:(noRed*(noRed-1)+noYel*(noYel-1))/((noRed+noYel)*(noRed+noYel-1));

feedbackvariables.text:
/* Node 1: Check correct probability */
/* Node 2: Worked solution */
outcomesH: if noH=3 then "HHH" else if noH=2 then "HHT,HTH,THH" else if noH=1 then "TTH,THT,HTT" else "TTT"
outcomesT: if noT=0 then "HHH" else if noT=1 then "HHT,HTH,THH" else if noT=2 then "TTH,THT,HTT" else "TTT"

/* Node 3: Check whether student has multiplied probabilities for H and T instead of adding */
sf_a:((if noH=0 or noH=3 then 1 else 3)*(if noT=0 or noT=3 then 1 else 3))/64

/* Node 1: Check correct probability */
/* Node 2: Worked solution */
rolls: if operation="sum" then (if total=5 then "(1,4), (2,3), (3,2), (4,1)" else if total=6 then "(1,5), (2,4), (3,3), (4,2), (5,1)" else if total=7 then "(1,6), (2,5), (3,4), (4,3), (5,2), (6,1)" else if total=8 then "(2,6), (3,5), (4,4), (5,3), (6,2)" else "(3,6), (4,5), (5,4), (6,3)") else (if total=4 then "(1,4), (2,2), (4,1)" else if total=6 then "(1,6), (2,3), (3,2), (6,1)" else "(2,6), (3,4), (4,3), (6,2)");

/* Node 3: Check whether given probability is smaller suggesting student has missed some correct rolls */
node3_test: if ans2>0 and ans2<probB and integerp(ans2*36) then 1 else 0;

/* Node 1: Check correct probability (3) */
/* Node 2: Worked solution */
/* Node 3: Check whether student has correctly answered problem WITH replacement (1) */
pc_c1:(noRed^2+noYel^2)/((noRed+noYel)^2);

/* Node 4: Check whether student has times probabilities for two reds and two yellows (1) */
pc_c2:(noRed*(noRed-1)*noYel*(noYel-1))/((noRed+noYel)*(noRed+noYel-1))^2;

/* Node 5: Check whether student has consistently used addition for "and" and multiplication for "or" */
sf_c:(noRed/(noRed+noYel)+(noRed-1)/(noRed+noYel-1))*(noYel/(noRed+noYel)+(noYel-1)/(noRed+noYel-1));
